// Pre-classify before sending to AI (reduces AI token cost)
const emails = $input.all();

const SPAM_PATTERNS = ['shopee', 'lazada', 'tiki', 'grab', 'noreply', 'no-reply', 'donotreply', 'unsubscribe'];
const PROMO_KW = ['giảm giá', 'flash sale', 'khuyến mãi', 'ưu đãi', '% off', 'sale', 'voucher', 'coupon'];

const preClassified = emails.map(item => {
  const e = item.json;
  const from = (e.from || '').toLowerCase();
  const subject = (e.subject || '').toLowerCase();
  const isObviousSpam = SPAM_PATTERNS.some(p => from.includes(p));
  const isObviousPromo = PROMO_KW.some(kw => subject.includes(kw));

  return {
    id: e.id,
    from: (e.from || '').replace(/<[^>]+>/g, '').trim(),
    subject: e.subject || '(no subject)',
    snippet: (e.snippet || e.textPlain || '').substring(0, 200),
    date: e.date,
    pre_category: isObviousSpam ? 'spam' : isObviousPromo ? 'promotion' : 'needs_ai_review'
  };
});

const needsReview = preClassified.filter(e => e.pre_category === 'needs_ai_review');
const obviousSpam = preClassified.filter(e => e.pre_category === 'spam');
const obviousPromo = preClassified.filter(e => e.pre_category === 'promotion');

console.log(`Pre-classified: ${obviousSpam.length} spam, ${obviousPromo.length} promo, ${needsReview.length} needs AI`);

return [{ json: {
  all_emails: preClassified,
  needs_ai_review: needsReview,
  obvious_spam: obviousSpam,
  obvious_promo: obviousPromo,
  total: emails.length
}}];

// Prepare AI prompt with only emails needing review
const data = $input.first().json;
const emailsForAI = data.needs_ai_review;

if (emailsForAI.length === 0) {
  return [{ json: { skip_ai: true, ...data } }];
}

const emailList = emailsForAI.map((e, i) =>
  `[${i+1}] From: ${e.from}\nSubject: ${e.subject}\nSnippet: ${e.snippet}`
).join('\n---\n');

const prompt = `Bạn là trợ lý quản lý email. Phân loại các email sau vào một trong các nhóm:
- IMPORTANT: Từ sếp/khách hàng/đối tác, có deadline, cần phản hồi
- WORK: Liên quan công việc nhưng không urgent
- PERSONAL: Email cá nhân/gia đình
- NEWSLETTER: Bản tin thông thường
- SPAM: Quảng cáo, rác

Email cần phân loại:
${emailList}

Trả lời dạng JSON array, mỗi item có: index (1-based), category, reason_vi (lý do bằng tiếng Việt, ngắn gọn), action ("keep_urgent"/"keep"/"archive"/"trash"), priority ("high"/"medium"/"low").

Chỉ trả JSON, không giải thích thêm.`;

return [{ json: { prompt, emails_for_ai: emailsForAI, pre_data: data } }];

// Parse AI response và kết hợp với pre-classification
const aiResponse = $input.first().json;
const prevData = $('🤖 Chuẩn Bị AI Prompt').first().json;

let aiResults = [];
try {
  const rawText = aiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
  const jsonMatch = rawText.match(/\[.*\]/s);
  if (jsonMatch) {
    aiResults = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  console.error('AI parse error:', e.message);
  // Fallback: treat all AI emails as 'work'
  aiResults = (prevData.emails_for_ai || []).map((_, i) => ({
    index: i + 1, category: 'WORK', action: 'keep', priority: 'medium',
    reason_vi: 'Không thể phân tích'
  }));
}

// Combine AI results with email data
const emailsForAI = prevData.emails_for_ai || [];
const aiClassified = aiResults.map(r => ({
  ...emailsForAI[r.index - 1],
  category: r.category,
  action: r.action,
  priority: r.priority,
  reason: r.reason_vi,
  classified_by: 'ai'
})).filter(Boolean);

// Merge all classifications
const preData = prevData.pre_data;
const allEmails = [
  ...aiClassified,
  ...(preData.obvious_spam || []).map(e => ({ ...e, category: 'SPAM', action: 'trash', priority: 'low', classified_by: 'rule' })),
  ...(preData.obvious_promo || []).map(e => ({ ...e, category: 'PROMOTION', action: 'archive', priority: 'low', classified_by: 'rule' }))
];

const grouped = {
  important: allEmails.filter(e => e.category === 'IMPORTANT'),
  work: allEmails.filter(e => e.category === 'WORK'),
  personal: allEmails.filter(e => e.category === 'PERSONAL'),
  newsletter: allEmails.filter(e => e.category === 'NEWSLETTER' || e.pre_category === 'newsletter'),
  promotion: allEmails.filter(e => e.category === 'PROMOTION' || e.pre_category === 'promotion'),
  spam: allEmails.filter(e => e.category === 'SPAM' || e.pre_category === 'spam')
};

return [{ json: { grouped, all: allEmails, total: preData.total || allEmails.length } }];

// Generate comprehensive Telegram report
const data = $input.first().json;
const { grouped, total } = data;

const dateStr = new Date().toLocaleDateString('vi-VN', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Ho_Chi_Minh'
});

const fmtSection = (arr, max = 3) => {
  if (!arr || arr.length === 0) return '_Không có_';
  const items = arr.slice(0, max).map((e, i) => {
    const tag = e.classified_by === 'ai' ? '🤖' : '⚡';
    const reason = e.reason ? ` _(${e.reason})_` : '';
    return `  ${i+1}. *${(e.subject||'').substring(0, 50)}*${reason}\n     📤 ${(e.from||'').substring(0, 38)} ${tag}`;
  }).join('\n');
  const more = arr.length > max ? `\n  _... và ${arr.length - max} email khác_` : '';
  return items + more;
};

// Build priority section
const urgentEmails = (grouped.important || []).filter(e => e.priority === 'high');
const urgentSection = urgentEmails.length > 0
  ? `\n🚨 *CẦN XỬ LÝ NGAY:*\n${fmtSection(urgentEmails)}`
  : '';

const cleanupCount = (grouped.spam?.length || 0) + (grouped.promotion?.length || 0);
const toTrashIds = (grouped.spam || []).map(e => e.id).filter(Boolean);
const toArchiveIds = (grouped.promotion || []).map(e => e.id).filter(Boolean);

const mainReport = `🤖 *BÁO CÁO EMAIL AI - SÁNG NAY*
📅 ${dateStr}
━━━━━━━━━━━━━━━━━━━━━━

📊 *Thống kê toàn bộ:*
• ⭐ Quan trọng: ${grouped.important?.length || 0} email
• 💼 Công việc: ${grouped.work?.length || 0} email
• 👤 Cá nhân: ${grouped.personal?.length || 0} email
• 📰 Newsletter: ${grouped.newsletter?.length || 0} email
• 🏷️ Khuyến mãi: ${grouped.promotion?.length || 0} email
• 🗑️ Spam: ${grouped.spam?.length || 0} email
• 📨 *Tổng: ${total} email*
${urgentSection}
━━━━━━━━━━━━━━━━━━━━━━

⭐ *QUAN TRỌNG:*
${fmtSection(grouped.important)}

💼 *CÔNG VIỆC:*
${fmtSection(grouped.work)}

━━━━━━━━━━━━━━━━━━━━━━
🧹 Tự động dọn: *${cleanupCount} email* (spam + promo)
🤖 Phân tích bởi Gemini AI`;

return [{ json: { mainReport, toTrashIds, toArchiveIds, grouped, total } }];

// Prepare spam IDs for trashing
const toTrashIds = $('📊 Tạo Báo Cáo AI').first().json.toTrashIds || [];
const toArchiveIds = $('📊 Tạo Báo Cáo AI').first().json.toArchiveIds || [];

if (toTrashIds.length === 0 && toArchiveIds.length === 0) {
  return [{ json: { nothing_to_clean: true } }];
}

const tasks = [
  ...toTrashIds.map(id => ({ emailId: id, action: 'trash' })),
  ...toArchiveIds.map(id => ({ emailId: id, action: 'archive' }))
];

console.log(`Cleanup tasks: ${tasks.length} (${toTrashIds.length} trash, ${toArchiveIds.length} archive)`);
return tasks.map(t => ({ json: t }));

const results = $input.all();
const report = $('📊 Tạo Báo Cáo AI').first().json;

console.log(`✅ V3 AI Pro completed: ${report.total} emails processed`);
console.log(`🗑️ Trashed: ${report.toTrashIds?.length || 0}`);
console.log(`📁 Archived: ${report.toArchiveIds?.length || 0}`);

return [{
  json: {
    status: 'completed',
    workflow_version: 'v3-ai-pro',
    total_processed: report.total,
    trashed: report.toTrashIds?.length || 0,
    archived: report.toArchiveIds?.length || 0,
    finished_at: new Date().toISOString()
  }
}];
